package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.UserinfoSignedResponseAlgVO;

class UserinfoSignedResponseAlgValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of userinfo signed response alg of oauth client")
  void test_userinfo_signed_response_alg_value_holder_assign_plain_value() {
    Object holder = new Object();
    UserinfoSignedResponseAlgValueHolder<Object> value =
        new UserinfoSignedResponseAlgValueHolder<>(holder);
    Assertions.assertSame(holder, value.userinfoSignedResponseAlg("one"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getUserinfoSignedResponseAlgValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getUserinfoSignedResponseAlg().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.userinfoSignedResponseAlgNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getUserinfoSignedResponseAlgValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getUserinfoSignedResponseAlg().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of userinfo signed response alg of oauth client")
  void test_userinfo_signed_response_alg_value_holder_assign_value_object() {
    Object holder = new Object();
    UserinfoSignedResponseAlgValueHolder<Object> value =
        new UserinfoSignedResponseAlgValueHolder<>(holder);
    UserinfoSignedResponseAlgVO vo = UserinfoSignedResponseAlgVO.from("one");
    Assertions.assertFalse(value.getUserinfoSignedResponseAlgValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.userinfoSignedResponseAlg(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getUserinfoSignedResponseAlgValue().orElseThrow());
    Assertions.assertSame(holder, value.userinfoSignedResponseAlg(Optional.empty()));
    Assertions.assertFalse(value.getUserinfoSignedResponseAlgValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.userinfoSignedResponseAlg(Optional.of(vo)));
    Assertions.assertSame(vo, value.getUserinfoSignedResponseAlgValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of userinfo signed response alg of oauth client against the original")
  void test_userinfo_signed_response_alg_value_holder_read() {
    Object holder = new Object();
    UserinfoSignedResponseAlgValueHolder<Object> value =
        new UserinfoSignedResponseAlgValueHolder<>(holder);
    UserinfoSignedResponseAlgVO vo = UserinfoSignedResponseAlgVO.from("one");
    UserinfoSignedResponseAlgVO other = UserinfoSignedResponseAlgVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getUserinfoSignedResponseAlgValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readUserinfoSignedResponseAlg(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readUserinfoSignedResponseAlg(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.userinfoSignedResponseAlg(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readUserinfoSignedResponseAlg(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readUserinfoSignedResponseAlg(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of userinfo signed response alg of oauth client")
  void test_userinfo_signed_response_alg_value_holder_unset() {
    Object holder = new Object();
    UserinfoSignedResponseAlgValueHolder<Object> value =
        new UserinfoSignedResponseAlgValueHolder<>(holder);
    UserinfoSignedResponseAlgVO vo = UserinfoSignedResponseAlgVO.from("one");
    value.userinfoSignedResponseAlg(vo);
    Assertions.assertSame(holder,
        value.unsetUserinfoSignedResponseAlgIfMatches("userinfoSignedResponseAlg_other"));
    Assertions.assertTrue(value.getUserinfoSignedResponseAlgValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetUserinfoSignedResponseAlgIfMatches("userinfoSignedResponseAlg"));
    Assertions.assertFalse(value.getUserinfoSignedResponseAlgValue().isPresent(),
        "The field name must clear the value");
    value.userinfoSignedResponseAlg(vo);
    Assertions.assertSame(holder, value.unsetUserinfoSignedResponseAlg());
    Assertions.assertFalse(value.getUserinfoSignedResponseAlgValue().isPresent(),
        "Unset must clear the value");
  }
}
